import type { BotBenchmarkMetric } from '@pierre-review/shared';

// The percentile lookups, ported ONE-FOR-ONE from `bot_monitor.panel.fit`'s `percentile_of` /
// `value_at_percentile` — which that module's docstring names "the reference implementation the
// serving side must match". Two implementations of one lookup is a divergence waiting to happen,
// so `test/benchmark-percentile.test.ts` pins this port against GOLDEN VECTORS generated by
// running the Python on the very grid the fixture carries.
//
// ⚠ THE MID-RANK CONVENTION ON FLAT REGIONS IS LOAD-BEARING, AND THE BOTTOM EDGE IS WHERE IT
// BITES. Rate metrics pile up on exactly 0.0 — a cell where a quarter of repositories never had a
// thread acted on has a grid whose first several knots are all 0.0. A customer sitting at 0.0 is
// then NOT "worse than everyone" (percentile 0, what a naive `value <= v[0] -> 0` returns) and NOT
// "better than a quarter of them" (percentile 25, what the last matching knot returns): they are
// TIED with a quarter of the cohort, and the honest answer is the middle of that tie. Both wrong
// answers are plausible-looking numbers, and neither shows up in a test whose fixture has distinct
// values at every knot — so the fixture deliberately has eight repositories on 0.0.
//
// Formally: with G = sup{p : Q(p) < value} (0 if empty) and F = inf{p : Q(p) > value} (100 if
// empty), the answer is (G + F) / 2 — fraction-below-plus-half-ties, read off a piecewise-linear
// inverse CDF.

const round4 = (x: number): number => Math.round(x * 1e4) / 1e4;

/** Where `value` sits in a fitted metric, 0-100. `null` if the metric was REFUSED — never 0, and
 *  never a plausible small number. The union arm is the guard; this is where it pays off. */
export function percentileOf(metric: BotBenchmarkMetric, value: number): number | null {
  if (metric.status !== 'fitted') return null;
  const { p, v } = metric.grid;
  if (p.length === 0 || p.length !== v.length) return null;
  const first = v[0] as number;
  const last = v[v.length - 1] as number;
  if (value < first) return 0;
  if (value > last) return 100;
  return round4((belowEdge(p, v, value) + aboveEdge(p, v, value)) / 2);
}

/** `sup{p : Q(p) < value}`, or 0 when nothing in the cohort is strictly below `value`. */
function belowEdge(knots: number[], values: number[], value: number): number {
  let last = -1;
  for (let i = 0; i < values.length; i += 1) if ((values[i] as number) < value) last = i;
  if (last < 0) return 0;
  if (last === values.length - 1) return knots[knots.length - 1] as number;
  const lo = values[last] as number;
  const hi = values[last + 1] as number;
  // `lo < value <= hi` here, so the segment cannot be flat and the division is safe.
  const span = (value - lo) / (hi - lo);
  const kLo = knots[last] as number;
  const kHi = knots[last + 1] as number;
  return kLo + span * (kHi - kLo);
}

/** `inf{p : Q(p) > value}`, or 100 when nothing in the cohort is strictly above `value`. */
function aboveEdge(knots: number[], values: number[], value: number): number {
  let firstAbove = -1;
  for (let i = 0; i < values.length; i += 1) {
    if ((values[i] as number) > value) {
      firstAbove = i;
      break;
    }
  }
  if (firstAbove < 0) return 100;
  if (firstAbove === 0) return knots[0] as number;
  const lo = values[firstAbove - 1] as number;
  const hi = values[firstAbove] as number;
  // `lo <= value < hi` here, so again the segment cannot be flat.
  const span = (value - lo) / (hi - lo);
  const kLo = knots[firstAbove - 1] as number;
  const kHi = knots[firstAbove] as number;
  return kLo + span * (kHi - kLo);
}

/** The metric value at `percentile` (0-100), interpolated on the grid — the inverse lookup.
 *  `numpy.interp`'s clamping semantics: outside the knot range it returns the nearest endpoint. */
export function valueAtPercentile(
  metric: BotBenchmarkMetric,
  percentile: number,
): number | null {
  if (metric.status !== 'fitted') return null;
  const { p, v } = metric.grid;
  if (p.length === 0 || p.length !== v.length) return null;
  if (percentile <= (p[0] as number)) return v[0] as number;
  const lastIdx = p.length - 1;
  if (percentile >= (p[lastIdx] as number)) return v[lastIdx] as number;
  for (let i = 1; i <= lastIdx; i += 1) {
    const hiP = p[i] as number;
    if (percentile <= hiP) {
      const loP = p[i - 1] as number;
      const loV = v[i - 1] as number;
      const hiV = v[i] as number;
      if (hiP === loP) return hiV;
      return loV + ((percentile - loP) / (hiP - loP)) * (hiV - loV);
    }
  }
  return v[lastIdx] as number;
}
